import {supabase} from '../lib/supabase';
export type InvestorRow={user_id:string;investor_code:string|null;full_name:string;status:string;units:number;ownership_percent:number;invested_amount:number;created_at:string};
export type OwnershipOfferingRow={id:string;name:string;code:string;status:string;unit_price:number;unit_ownership_percent:number;total_units:number;allocated_units:number;available_units:number};

export type InquiryRow={id:string;name:string;email:string;phone:string|null;organization:string|null;message:string;source_page:string|null;status:string;created_at:string};
export async function listEquityInquiries(){const {data,error}=await client().from('portal_inquiries').select('id,name,email,phone,organization,message,source_page,status,created_at').eq('source_page','equity-interest').order('created_at',{ascending:false});if(error)throw error;return (data||[]) as InquiryRow[]}
export async function setInquiryStatus(id:string,status:'new'|'in_progress'|'closed'){const {error}=await client().schema('app').rpc('set_portal_inquiry_status',{p_inquiry_id:id,p_status:status});if(error)throw error}
export async function convertInquiryToInvestor(inquiry_id:string,investor_id:string){const {error}=await client().schema('app').rpc('convert_portal_inquiry_to_investor',{p_inquiry_id:inquiry_id,p_investor_id:investor_id});if(error)throw error}
export async function findInvestorByEmail(email:string){const normalized=email.trim().toLowerCase();const {data,error}=await client().schema('app').rpc('find_investor_by_email',{p_email:normalized});if(error)throw error;const row=Array.isArray(data)?data[0]:data;if(!row)return null;return row as {id:string;reference_code:string;legal_name:string;status:string;email:string}}
export type DistributionRow={id:string;investor_user_id:string;period:string;amount:number;status:string;paid_at:string|null;notes:string|null;created_at:string};
export type FinanceRow={id:string;entry_date:string;type:'income'|'expense';category:string;description:string;amount:number;reference_no:string|null;cost_class?:string|null;invoice_reference?:string|null;vendor_name?:string|null;tax_amount?:number;source_entity_type?:'finance_payment'|'finance_refund'|'finance_expense'|'finance_adjustment';source_entity_id?:string;adjustment_kind?:string|null;account_side?:'revenue'|'expense'|null;reason?:string|null};
export type DocumentRow={id:string;title:string;category:string;file_url:string;audience:string;published:boolean;status:string;created_at:string;current_version_id:string|null;version_created_by:string|null;approved_by:string|null;approved_at:string|null;published_at:string|null};
const client=()=>{if(!supabase)throw new Error('Supabase belum dikonfigurasi.');return supabase};
async function cleanupUnreferencedFinanceAsset(assetId:string,path:string){const abandoned=await client().schema('app').rpc('abandon_unreferenced_finance_asset',{p_asset_id:assetId});if(abandoned.error){console.warn('Finance asset cleanup abandonment failed',{assetId,path,error:abandoned.error});return}const removed=await client().storage.from('company-documents').remove([String(abandoned.data||path)]);if(removed.error)console.warn('Finance asset cleanup storage removal failed',{assetId,path,error:removed.error})}
export async function listOwnershipOfferings(){const {data,error}=await client().from('ownership_offerings').select('id,name,code,status,unit_price,unit_ownership_bps,total_units,ownership_holdings(units,status)').eq('status','open').order('created_at',{ascending:false});if(error)throw error;return(data||[]).map((o:any)=>{const allocated=(o.ownership_holdings||[]).filter((h:any)=>['reserved','active'].includes(h.status)).reduce((s:number,h:any)=>s+Number(h.units||0),0);return{id:o.id,name:o.name,code:o.code,status:o.status,unit_price:Number(o.unit_price||0),unit_ownership_percent:Number(o.unit_ownership_bps||0)/100,total_units:Number(o.total_units||0),allocated_units:allocated,available_units:Math.max(0,Number(o.total_units||0)-allocated)}}) as OwnershipOfferingRow[]}
export async function allocateInvestorOwnership(input:{offering_id:string;investor_id:string;units:number;acquisition_reference?:string;notes?:string}){const {error}=await client().schema('app').rpc('allocate_ownership_holding',{p_offering_id:input.offering_id,p_investor_id:input.investor_id,p_units:input.units,p_acquisition_reference:input.acquisition_reference?.trim()||null,p_notes:input.notes?.trim()||null});if(error)throw error}
export type OwnershipInvariantHealth={active_investors_without_active_holding:number;approved_investors_with_active_holding:number;inactive_investors_with_active_holding:number;holding_unit_bps_mismatches:number;checked_at:string};
export async function getOwnershipInvariantHealth(){const {data,error}=await client().rpc('get_ownership_invariant_health');if(error)throw error;const x:any=data||{};return {active_investors_without_active_holding:Number(x.active_investors_without_active_holding||0),approved_investors_with_active_holding:Number(x.approved_investors_with_active_holding||0),inactive_investors_with_active_holding:Number(x.inactive_investors_with_active_holding||0),holding_unit_bps_mismatches:Number(x.holding_unit_bps_mismatches||0),checked_at:String(x.checked_at||'')} as OwnershipInvariantHealth}
export async function listInvestors(){const {data,error}=await client().from('investors').select('id,reference_code,legal_name,status,created_at,ownership_holdings(units,ownership_bps,status,acquisition_investment_value)').order('created_at',{ascending:false});if(error)throw error;return (data||[]).map((r:any)=>{const holdings=(r.ownership_holdings||[]).filter((h:any)=>h.status==='active'||h.status==='reserved');const units=holdings.reduce((n:number,h:any)=>n+Number(h.units||0),0);const bps=holdings.reduce((n:number,h:any)=>n+Number(h.ownership_bps||0),0);return {user_id:r.id,investor_code:r.reference_code,full_name:r.legal_name,status:r.status,units,ownership_percent:bps/100,invested_amount:holdings.reduce((n:number,h:any)=>n+Number(h.acquisition_investment_value||0),0),created_at:r.created_at}}) as InvestorRow[]}
export async function setInvestorStatus(user_id:string,status:string){const allowed=['prospective','submitted','under_review','approved','rejected','inactive'];if(!allowed.includes(status))throw new Error(status==='active'?'Aktivasi investor wajib dilakukan setelah alokasi kepemilikan.':'Status investor tidak valid.');const {error}=await client().rpc('transition_investor',{p_investor_id:user_id,p_to_status:status,p_reason:null});if(error)throw error}
export async function activateInvestorAfterOwnershipAllocation(user_id:string){const {error}=await client().schema('app').rpc('activate_investor_after_ownership_allocation',{p_investor_id:user_id});if(error)throw error}
export async function listInvestorDistributions(user_id:string){const {data,error}=await client().from('profit_distribution_allocations').select('id,investor_id,allocation_amount,status,paid_at,payment_reference,created_at,profit_distributions(period_start,period_end,notes)').eq('investor_id',user_id).order('created_at',{ascending:false});if(error)throw error;return (data||[]).map((r:any)=>{const d=Array.isArray(r.profit_distributions)?r.profit_distributions[0]:r.profit_distributions;return {id:r.id,investor_user_id:r.investor_id,period:d?String(d.period_start)+' — '+String(d.period_end):'—',amount:Number(r.allocation_amount||0),status:r.status,paid_at:r.paid_at,notes:r.payment_reference||d?.notes||null,created_at:r.created_at}}) as DistributionRow[]}
export async function listPayableDistributions(){const [{data,error},{data:workflow,error:workflowError}]=await Promise.all([client().from('profit_distribution_allocations').select('id,investor_id,holding_id,ownership_bps,investor_pool_share_bps,allocation_amount,status,payment_reference,paid_at,created_at,investor_reference_snapshot,investor_legal_name_snapshot,bank_name_snapshot,bank_account_name_snapshot,bank_account_number_snapshot,payout_snapshot_at,units_snapshot,investment_value_snapshot,offering_code_snapshot,financial_report_version_id_snapshot,financial_report_title_snapshot,investors(reference_code,legal_name,bank_name,bank_account_name,bank_account_number),profit_distributions(id,period_start,period_end,revenue_amount,operating_expense_amount,opex_rate_bps,opex_amount,profit_amount,investor_pool_bps,investor_pool_amount,status,paid_at)').in('status',['payable','paid']).order('created_at',{ascending:false}),client().schema('app').rpc('get_profit_distribution_payout_workflow')]);if(error)throw error;if(workflowError)throw workflowError;const byId=new Map((workflow||[]).map((x:any)=>[x.allocation_id,x]));return (data||[]).map((x:any)=>({...x,payout_workflow:byId.get(x.id)||{has_proof:false,payment_reference:null,uploaded_by_is_me:false}}))}
export async function uploadInvestorDistributionProof(input:{allocation_id:string;investor_id:string;payment_reference:string;proof:File}){const ref=input.payment_reference.trim();if(!ref)throw new Error('Referensi pembayaran wajib diisi.');if(!input.proof)throw new Error('Bukti transfer wajib diunggah.');const safe=input.proof.name.replace(/[^a-zA-Z0-9._-]/g,'-');const uploadedPath=input.investor_id+'/'+input.allocation_id+'/'+Date.now()+'-'+safe;const up=await client().storage.from('profit-distribution-proofs').upload(uploadedPath,input.proof,{contentType:input.proof.type||'application/octet-stream',upsert:false});if(up.error)throw up.error;const ins=await client().schema('app').rpc('register_profit_distribution_payment_proof',{p_allocation_id:input.allocation_id,p_storage_path:uploadedPath,p_original_file_name:input.proof.name,p_mime_type:input.proof.type||'application/octet-stream',p_file_size_bytes:input.proof.size,p_payment_reference:ref});if(ins.error){await client().storage.from('profit-distribution-proofs').remove([uploadedPath]);throw ins.error}}
export async function markInvestorDistributionPaid(input:{allocation_id:string;payment_reference:string}){const {error}=await client().schema('app').rpc('mark_profit_distribution_allocation_paid',{p_allocation_id:input.allocation_id,p_payment_reference:input.payment_reference.trim()||null});if(error)throw error}
export async function listFinance(){const [payments,refunds,expenses,adjustments]=await Promise.all([client().from('finance_payments').select('id,received_at,created_at,reference,external_reference,amount,notes,status').eq('status','confirmed').order('created_at',{ascending:false}),client().from('finance_refunds').select('id,processed_at,created_at,reference,amount,reason,status').eq('status','processed').order('created_at',{ascending:false}),client().from('finance_expenses').select('id,expense_on,created_at,reference,total_amount,category,description,status,cost_class,vendor_name,tax_amount,finance_invoices(reference)').order('created_at',{ascending:false}),client().from('finance_adjustments').select('id,adjustment_no,posted_on,source_entity_type,source_entity_id,adjustment_kind,account_side,cost_class,amount_delta,reason,status').eq('status','posted').order('created_at',{ascending:false})]);if(payments.error)throw payments.error;if(refunds.error)throw refunds.error;if(expenses.error)throw expenses.error;if(adjustments.error)throw adjustments.error;const rows:FinanceRow[]=[...(payments.data||[]).map((x:any)=>({id:'payment-'+x.id,entry_date:(x.received_at||x.created_at).slice(0,10),type:'income' as const,category:'Pembayaran Invoice',description:x.notes||'Penerimaan pembayaran',amount:Number(x.amount),reference_no:x.external_reference||x.reference||null,source_entity_type:'finance_payment' as const,source_entity_id:x.id})),...(refunds.data||[]).map((x:any)=>({id:'refund-'+x.id,entry_date:(x.processed_at||x.created_at).slice(0,10),type:'expense' as const,category:'Refund',description:x.reason||'Refund transaksi',amount:Number(x.amount),reference_no:x.reference||null,source_entity_type:'finance_refund' as const,source_entity_id:x.id})),...(expenses.data||[]).filter((x:any)=>x.status!=='void'&&x.status!=='cancelled').map((x:any)=>({id:'expense-'+x.id,entry_date:x.expense_on,type:'expense' as const,category:x.category,description:x.description,amount:Number(x.total_amount),reference_no:x.reference||null,cost_class:x.cost_class||null,invoice_reference:(Array.isArray(x.finance_invoices)?x.finance_invoices[0]?.reference:x.finance_invoices?.reference)||null,vendor_name:x.vendor_name||null,tax_amount:Number(x.tax_amount||0),source_entity_type:'finance_expense' as const,source_entity_id:x.id})),...(adjustments.data||[]).map((x:any)=>({id:'adjustment-'+x.id,entry_date:x.posted_on,type:(x.account_side==='revenue'&&Number(x.amount_delta)>=0?'income':'expense') as 'income'|'expense',category:'Koreksi '+(x.account_side==='revenue'?'Pendapatan':'Beban'),description:x.reason,amount:Number(x.amount_delta),reference_no:x.adjustment_no,cost_class:x.cost_class||null,source_entity_type:'finance_adjustment' as const,source_entity_id:x.id,adjustment_kind:x.adjustment_kind,account_side:x.account_side,reason:x.reason}))];return rows.sort((a,b)=>b.entry_date.localeCompare(a.entry_date))}
export type FinanceCostClass='direct_cost'|'agent_fee'|'partner_fee'|'marketing_fee'|'payment_fee'|'operating_expense'|'tax'|'other';
export type FinanceInvoiceMargin={invoice_id:string;reference:string;status:string;gross_sales:number;processed_refunds:number;net_sales:number;estimated_hpp:number;estimated_margin:number;estimated_margin_percent:number;actual_hpp:number;agent_fee:number;partner_fee:number;marketing_fee:number;payment_fee:number;allocated_operating_expense:number;tax_expense:number;other_cost:number;actual_transaction_cost:number;real_margin:number;real_margin_percent:number};
export async function getFinanceInvoiceMargin(invoiceId:string){const {data,error}=await client().schema('app').rpc('finance_invoice_margin',{p_invoice_id:invoiceId});if(error)throw error;const x:any=data||{};const nums=['gross_sales','processed_refunds','net_sales','estimated_hpp','estimated_margin','estimated_margin_percent','actual_hpp','agent_fee','partner_fee','marketing_fee','payment_fee','allocated_operating_expense','tax_expense','other_cost','actual_transaction_cost','real_margin','real_margin_percent'];for(const k of nums)x[k]=Number(x[k]||0);return x as FinanceInvoiceMargin}
export async function listExpenseLinkableInvoices(){const {data,error}=await client().from('finance_invoices').select('id,invoice_number,customer_name,grand_total,status').not('status','eq','void').order('created_at',{ascending:false}).limit(200);if(error)throw error;return data||[]}
export async function addFinance(input:Omit<FinanceRow,'id'> & {receipt:File;cost_class?:FinanceCostClass;invoice_id?:string|null;vendor_name?:string|null;tax_amount?:number;payment_method?:string}){if(input.type!=='expense')throw new Error('Pemasukan berasal otomatis dari pembayaran invoice production.');if(!input.receipt)throw new Error('Bukti pengeluaran wajib diunggah.');const costClass=input.cost_class||'operating_expense';if(costClass==='direct_cost'&&!input.invoice_id)throw new Error('HPP / Direct Cost wajib ditautkan ke invoice penjualan.');if(Number(input.tax_amount||0)<0||Number(input.tax_amount||0)>input.amount)throw new Error('Nilai pajak tidak valid.');const safe=input.receipt.name.replace(/[^a-zA-Z0-9._-]/g,'-');const path='finance/expenses/'+crypto.randomUUID()+'-'+safe;const up=await client().storage.from('company-documents').upload(path,input.receipt,{contentType:input.receipt.type||'application/octet-stream',upsert:false});if(up.error)throw up.error;const asset=await client().schema('app').rpc('register_finance_expense_receipt',{p_path:path,p_original_filename:input.receipt.name,p_mime_type:input.receipt.type||'application/octet-stream',p_byte_size:input.receipt.size});if(asset.error){await client().storage.from('company-documents').remove([path]);throw asset.error}const recorded=await client().schema('app').rpc('record_linked_finance_expense',{p_expense_on:input.entry_date,p_category:input.category,p_vendor_name:input.vendor_name||null,p_description:input.description,p_amount:input.amount,p_tax_amount:Number(input.tax_amount||0),p_cost_class:costClass,p_invoice_id:input.invoice_id||null,p_receipt_asset_id:asset.data,p_reference:input.reference_no||null,p_payment_method:input.payment_method||'Transfer',p_idempotency_key:crypto.randomUUID()});if(recorded.error){await cleanupUnreferencedFinanceAsset(String(asset.data),path);throw recorded.error}}

export type FinanceAdjustmentSourceSummary={source_entity_type:string;source_entity_id:string;source_amount:number;source_account_side:'revenue'|'expense';source_cost_class:FinanceCostClass|null;source_date:string;correction_total:number;reversal_total:number;adjustment_count:number;has_reversal:boolean;remaining_reversible_amount:number};
export async function getFinanceAdjustmentSourceSummary(source_entity_type:string,source_entity_id:string){const {data,error}=await client().schema('app').rpc('finance_adjustment_source_summary',{p_source_entity_type:source_entity_type,p_source_entity_id:source_entity_id});if(error)throw error;const x:any=data||{};return {...x,source_amount:Number(x.source_amount||0),correction_total:Number(x.correction_total||0),reversal_total:Number(x.reversal_total||0),adjustment_count:Number(x.adjustment_count||0),remaining_reversible_amount:Number(x.remaining_reversible_amount||0)} as FinanceAdjustmentSourceSummary}
export type FinancialPeriodAdjustmentDisclosure={period_id:string;adjustment_count:number;revenue_adjustments:number;expense_adjustments:number;net_profit_impact:number;prior_period_adjustments:Array<{adjustment_id:string;adjustment_no:string;posted_on:string;source_entity_type:string;source_entity_id:string;adjustment_kind:string;account_side:'revenue'|'expense';cost_class:FinanceCostClass|null;amount_delta:number;reason:string;source_period_id:string|null;source_period_start:string|null;source_period_end:string|null}>};
export async function getFinancialPeriodAdjustmentDisclosure(periodId:string){const {data,error}=await client().schema('app').rpc('financial_period_adjustment_disclosure',{p_period_id:periodId});if(error)throw error;const x:any=data||{};return {...x,adjustment_count:Number(x.adjustment_count||0),revenue_adjustments:Number(x.revenue_adjustments||0),expense_adjustments:Number(x.expense_adjustments||0),net_profit_impact:Number(x.net_profit_impact||0),prior_period_adjustments:(x.prior_period_adjustments||[]).map((a:any)=>({...a,amount_delta:Number(a.amount_delta||0)}))} as FinancialPeriodAdjustmentDisclosure}
export type FinanceAdjustmentInput={financial_period_id:string;source_entity_type:'finance_expense'|'finance_payment'|'finance_refund'|'financial_report';source_entity_id:string;adjustment_kind:'correction'|'reversal';account_side:'revenue'|'expense';cost_class?:FinanceCostClass|null;amount_delta:number;reason:string;evidence?:File|null};
export async function postFinanceAdjustment(input:FinanceAdjustmentInput){let assetId:string|null=null;let uploadedPath:string|null=null;if(input.evidence){const safe=input.evidence.name.replace(/[^a-zA-Z0-9._-]/g,'-');uploadedPath='finance/adjustments/'+crypto.randomUUID()+'-'+safe;const up=await client().storage.from('company-documents').upload(uploadedPath,input.evidence,{contentType:input.evidence.type||'application/octet-stream',upsert:false});if(up.error)throw up.error;const reg=await client().schema('app').rpc('register_finance_adjustment_evidence',{p_path:uploadedPath,p_original_filename:input.evidence.name,p_mime_type:input.evidence.type||'application/octet-stream',p_byte_size:input.evidence.size});if(reg.error){await client().storage.from('company-documents').remove([uploadedPath]);throw reg.error}assetId=String(reg.data)}const {data,error}=await client().schema('app').rpc('post_finance_adjustment',{p_financial_period_id:input.financial_period_id,p_source_entity_type:input.source_entity_type,p_source_entity_id:input.source_entity_id,p_adjustment_kind:input.adjustment_kind,p_account_side:input.account_side,p_cost_class:input.account_side==='expense'?(input.cost_class||'other'):null,p_amount_delta:input.amount_delta,p_reason:input.reason.trim(),p_evidence_asset_id:assetId,p_idempotency_key:crypto.randomUUID()});if(error){if(assetId&&uploadedPath)await cleanupUnreferencedFinanceAsset(assetId,uploadedPath);throw error}return String(data)}
export async function listOpenFinancialPeriods(){const {data,error}=await client().from('financial_periods').select('id,period_type,fiscal_year,period_index,starts_on,ends_on,status').eq('status','open').order('starts_on',{ascending:false});if(error)throw error;return data||[]}

export async function listDocuments(){const {data,error}=await client().from('documents').select('id,title,kind,visibility,status,created_at,current_version_id,current_version:document_versions!documents_current_version_fk(created_by,approved_by,approved_at,published_at)').order('created_at',{ascending:false});if(error)throw error;return (data||[]).map((d:any)=>{const v=Array.isArray(d.current_version)?d.current_version[0]:d.current_version;return{id:d.id,title:d.title,category:d.kind,file_url:'',audience:d.visibility,published:d.status==='published',status:d.status,created_at:d.created_at,current_version_id:d.current_version_id||null,version_created_by:v?.created_by||null,approved_by:v?.approved_by||null,approved_at:v?.approved_at||null,published_at:v?.published_at||null}}) as DocumentRow[]}
export async function uploadPortalDocument(input:{file:File;title:string;category:string;audience:'public'|'investor'|'restricted'|'internal';published:boolean}){if(input.file.type!=='application/pdf'&&!input.file.name.toLowerCase().endsWith('.pdf'))throw new Error('Dokumen wajib berformat PDF.');const user=(await client().auth.getUser()).data.user;if(!user)throw new Error('Sesi admin tidak tersedia.');const safe=input.file.name.replace(/[^a-zA-Z0-9._-]/g,'-');const path=`${crypto.randomUUID()}-${safe}`;const up=await client().storage.from('company-documents').upload(path,input.file,{contentType:'application/pdf',upsert:false});if(up.error)throw up.error;const asset=await client().schema('app').rpc('register_portal_document_asset',{p_path:path,p_original_filename:input.file.name,p_mime_type:'application/pdf',p_byte_size:input.file.size});if(asset.error){await client().storage.from('company-documents').remove([path]);throw asset.error}const kind=['investment_proposal','pitch_deck','investor_report','business_update','supporting'].includes(input.category)?input.category:'supporting';const visibility=input.audience==='investor'?'investors':input.audience;const slug=(input.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'dokumen')+'-'+crypto.randomUUID().slice(0,8);const created=await client().schema('app').rpc('create_document_with_draft',{p_title:input.title,p_slug:slug,p_kind:kind,p_summary:null,p_visibility:visibility,p_file_asset_id:asset.data.id});if(created.error){const abandoned=await client().schema('app').rpc('abandon_unreferenced_portal_document_asset',{p_asset_id:asset.data.id});if(!abandoned.error)await client().storage.from('company-documents').remove([String(abandoned.data||path)]);throw created.error}if(input.published)throw new Error('Auto-publish dinonaktifkan. Dokumen wajib melewati workflow review, approval, dan publish terpisah.')}
export async function transitionDocument(id:string,target:'review'|'approved'|'published'|'archived'){const {error}=await client().schema('app').rpc('transition_document_publication',{p_document_id:id,p_target:target});if(error)throw error}
export async function setDocumentPublished(id:string,published:boolean){return transitionDocument(id,published?'published':'archived')}
export async function grantDocumentToInvestor(document_id:string,investor_id:string,note?:string){const user=(await client().auth.getUser()).data.user;if(!user)throw new Error('Sesi admin tidak tersedia.');const {error}=await client().from('document_access_grants').insert({document_id,investor_id,granted_by:user.id,note:note||null});if(error)throw error}
export async function listDocumentGrants(document_id:string){const {data,error}=await client().from('document_access_grants').select('id,investor_id,granted_at,revoked_at,note,investors(reference_code,legal_name)').eq('document_id',document_id).order('granted_at',{ascending:false});if(error)throw error;return data||[]}
