export async function createSalesInvoice(input:{customer_name:string;customer_email?:string;customer_phone?:string;product_type:string;product_name:string;product_code?:string;pax:number;departure_date?:string;due_date?:string;total_amount:number;estimated_hpp_total?:number;idempotency_key:string}){const unitPrice=input.pax>0?input.total_amount/input.pax:input.total_amount;const {data,error}=await financeRpc().rpc('create_finance_invoice',{p_customer_name:input.customer_name,p_customer_email:input.customer_email||null,p_customer_phone:input.customer_phone||null,p_customer_address:null,p_due_on:input.due_date||null,p_notes:input.product_type,p_items:[{name:input.product_name,product_code:input.product_code||null,description:input.product_type,quantity:input.pax,unit_label:'pax',unit_price:unitPrice,discount_amount:0,tax_rate:0,estimated_unit_cost:input.pax>0?Number(input.estimated_hpp_total||0)/input.pax:Number(input.estimated_hpp_total||0)}],p_idempotency_key:input.idempotency_key});if(error)throw error;const id=String(data);if(input.departure_date){const d=await financeRpc().rpc('set_finance_invoice_departure',{p_invoice_id:id,p_departure_on:input.departure_date});if(d.error)throw d.error}return (await listSalesInvoices()).find(x=>x.id===id)!}
export async function postSalesPayment(input:{invoice_id:string;amount:number;kind:'payment'|'refund';method:string;reference_no?:string;notes?:string;payment_id?:string;idempotency_key?:string}){if(input.kind==='payment'){const {error}=await financeRpc().rpc('record_finance_payment',{p_invoice_id:input.invoice_id,p_amount:input.amount,p_method:input.method,p_received_at:new Date().toISOString(),p_external_reference:input.reference_no||null,p_notes:input.notes||null,p_idempotency_key:input.idempotency_key||crypto.randomUUID()});if(error)throw error;return}const payments=await listSalesPayments(input.invoice_id);const confirmed=payments.filter(p=>p.kind==='payment'&&p.status==='confirmed');const payment=input.payment_id?confirmed.find(p=>p.id===input.payment_id):confirmed.length===1?confirmed[0]:null;if(!payment)throw new Error(confirmed.length>1?'Pilih pembayaran terkonfirmasi yang akan direfund.':'Refund memerlukan pembayaran terkonfirmasi.');const {error}=await financeRpc().rpc('request_finance_refund',{p_invoice_id:input.invoice_id,p_payment_id:payment.id,p_amount:input.amount,p_reason:input.notes||'Refund transaksi',p_notes:input.reference_no||null,p_idempotency_key:input.idempotency_key||crypto.randomUUID()});if(error)throw error}
