export async function reconcileSalesPayment(input:{payment_id:string;invoice_id:string;bank_reference:string;bank_amount:number;bank_received_at?:string;notes?:string;proof:File}){if(!input.proof)throw new Error('Bukti pembayaran wajib diunggah.');const user=(await client().auth.getUser()).data.user;if(!user)throw new Error('Sesi admin tidak tersedia.');const safe=input.proof.name.replace(/[^a-zA-Z0-9._-]/g,'-');const path='finance/'+input.invoice_id+'/'+input.payment_id+'/'+Date.now()+'-'+safe;const up=await client().storage.from('company-documents').upload(path,input.proof,{contentType:input.proof.type||'application/octet-stream',upsert:false});if(up.error)throw up.error;const asset=await client().schema('app').rpc('register_finance_payment_proof_asset',{p_path:path,p_original_filename:input.proof.name,p_mime_type:input.proof.type||'application/octet-stream',p_byte_size:input.proof.size});if(asset.error){await client().storage.from('company-documents').remove([path]);throw asset.error}const {error}=await financeRpc().rpc('reconcile_finance_payment',{p_payment_id:input.payment_id,p_proof_asset_id:asset.data,p_bank_reference:input.bank_reference.trim(),p_bank_amount:input.bank_amount,p_bank_received_at:input.bank_received_at||new Date().toISOString(),p_notes:input.notes||null});if(error){await cleanupUnreferencedFinanceAsset(String(asset.data),path);throw error}}
