export async function processApprovedSalesRefund(input:{refundId:string;invoiceId:string;bankReference:string;proof:File}){if(!input.proof)throw new Error('Bukti refund wajib diunggah.');if(!input.bankReference.trim())throw new Error('Referensi transaksi refund wajib diisi.');const safe=input.proof.name.replace(/[^a-zA-Z0-9._-]/g,'-');const path='finance/refunds/'+input.invoiceId+'/'+input.refundId+'/'+Date.now()+'-'+safe;const up=await client().storage.from('company-documents').upload(path,input.proof,{contentType:input.proof.type||'application/octet-stream',upsert:false});if(up.error)throw up.error;const asset=await client().schema('app').rpc('register_finance_refund_proof_asset',{p_path:path,p_original_filename:input.proof.name,p_mime_type:input.proof.type||'application/octet-stream',p_byte_size:input.proof.size});if(asset.error){await client().storage.from('company-documents').remove([path]);throw asset.error}const {error}=await financeRpc().rpc('process_approved_finance_refund',{p_refund_id:input.refundId,p_proof_asset_id:asset.data,p_bank_reference:input.bankReference.trim()});if(error){await cleanupUnreferencedFinanceAsset(String(asset.data),path);throw error}}
export async function listSalesPayments(invoice_id:string){const [p,r]=await Promise.all([client().from('finance_payments').select('*').eq('invoice_id',invoice_id).order('created_at',{ascending:true}),client().from('finance_refunds').select('*').eq('invoice_id',invoice_id).order('created_at',{ascending:true})]);if(p.error)throw p.error;if(r.error)throw r.error;return [...(p.data||[]).map((x:any)=>({id:x.id,invoice_id:x.invoice_id,payment_date:x.received_at||x.created_at,amount:Number(x.amount),kind:'payment' as const,method:x.method,reference_no:x.external_reference||x.reference,notes:x.notes,status:x.status,created_at:x.created_at})),...(r.data||[]).map((x:any)=>({id:x.id,invoice_id:x.invoice_id,payment_date:x.processed_at||x.created_at,amount:Number(x.amount),kind:'refund' as const,method:'Refund',reference_no:x.reference,notes:x.reason||x.notes,status:x.status,created_at:x.created_at}))] as SalesPayment[]}
