export async function getFinancialReportProfitLoss(reportId:string){const {data,error}=await client().schema('app').rpc('financial_report_profit_loss_breakdown',{p_report_id:reportId});if(error)throw error;return data as ProfitLossBreakdown}

export async function uploadFinancialReportAttachment(file:File){if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))throw new Error('Lampiran laporan wajib PDF.');const user=(await client().auth.getUser()).data.user;if(!user)throw new Error('Sesi admin tidak tersedia.');const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'-');const path=user.id+'/'+crypto.randomUUID()+'-'+safe;const up=await client().storage.from('financial-documents').upload(path,file,{contentType:'application/pdf',upsert:false});if(up.error)throw up.error;const asset=await client().schema('app').rpc('register_financial_report_asset',{p_path:path,p_original_filename:file.name,p_mime_type:'application/pdf',p_byte_size:file.size});if(asset.error){await client().storage.from('financial-documents').remove([path]);throw asset.error}return asset.data as string}
export async function saveFinancialReportContent(input:{reportId:string;documentAssetId:string;revenue:number;expense:number;pax:number;profitLoss?:ProfitLossBreakdown}){const p=input.profitLoss;const lineItems=[{statement:'income',category:'revenue',line_key:'revenue_total',label:'Pendapatan Bersih',amount:input.revenue,currency:'IDR',position:1,note:'Pembayaran confirmed dikurangi refund processed.'},{statement:'income',category:'expense',line_key:'hpp_total',label:'HPP / Direct Cost',amount:p?.hpp||0,currency:'IDR',position:2,note:''},{statement:'income',category:'revenue',line_key:'gross_profit',label:'Laba Kotor',amount:p?.gross_profit??input.revenue,currency:'IDR',position:3,note:''},{statement:'income',category:'expense',line_key:'agent_fee_total',label:'Fee Agen',amount:p?.agent_fee||0,currency:'IDR',position:4,note:''},{statement:'income',category:'expense',line_key:'partner_fee_total',label:'Fee Mitra',amount:p?.partner_fee||0,currency:'IDR',position:5,note:''},{statement:'income',category:'expense',line_key:'marketing_fee_total',label:'Fee Marketing / Referral',amount:p?.marketing_fee||0,currency:'IDR',position:6,note:''},{statement:'income',category:'expense',line_key:'payment_fee_total',label:'Fee Transaksi / Payment',amount:p?.payment_fee||0,currency:'IDR',position:7,note:''},{statement:'income',category:'expense',line_key:'operating_expense_total',label:'Beban Operasional',amount:p?.operating_expense||0,currency:'IDR',position:8,note:''},{statement:'income',category:'expense',line_key:'tax_expense_total',label:'Beban Pajak',amount:p?.tax_expense||0,currency:'IDR',position:9,note:''},{statement:'income',category:'expense',line_key:'other_expense_total',label:'Beban Lainnya',amount:p?.other_expense||0,currency:'IDR',position:10,note:''},{statement:'income',category:'expense',line_key:'expense_total',label:'Total Beban',amount:input.expense,currency:'IDR',position:11,note:'Total canonical seluruh recorded expense.'},{statement:'income',category:'revenue',line_key:'net_profit',label:'Laba Bersih',amount:p?.net_profit??input.revenue-input.expense,currency:'IDR',position:12,note:''}];const kpis=[{kpi_key:'pax_total',label:'Total Pax',value:input.pax,unit:'count',basis:'reported',position:1},{kpi_key:'gross_margin_percent',label:'Gross Margin',value:p?.gross_margin_percent||0,unit:'percent',basis:'canonical',position:2},{kpi_key:'net_margin_percent',label:'Net Margin',value:p?.net_margin_percent||0,unit:'percent',basis:'canonical',position:3}];const {data,error}=await client().schema('app').rpc('save_financial_report_draft_content',{p_report_id:input.reportId,p_document_asset_id:input.documentAssetId,p_line_items:lineItems,p_kpis:kpis});if(error){try{const abandoned=await client().schema('app').rpc('abandon_unreferenced_financial_report_asset',{p_asset_id:input.documentAssetId});if(abandoned.error){console.warn('Gagal melepas asset laporan keuangan yang belum terpakai.',abandoned.error)}else{const removed=await client().storage.from('financial-documents').remove([String(abandoned.data)]);if(removed.error)console.warn('Gagal menghapus file laporan keuangan yang sudah dilepas.',removed.error)}}catch(cleanupError){console.warn('Cleanup lampiran laporan keuangan gagal.',cleanupError)}throw error}return data}

export type ProfitDistributionRow={id:string;offering_id:string;financial_report_version_id:string;period_start:string;period_end:string;revenue_amount:number;opex_amount:number;profit_amount:number;company_share_bps:number;investor_pool_bps:number;investor_pool_amount:number;status:string;notes:string|null;created_by:string|null;approved_by:string|null;payable_by:string|null;payable_at:string|null};
export async function listProfitDistributions(){const {data,error}=await client().from('profit_distributions').select('id,offering_id,financial_report_version_id,period_start,period_end,revenue_amount,opex_amount,profit_amount,company_share_bps,investor_pool_bps,investor_pool_amount,status,notes,created_by,approved_by,payable_by,payable_at').order('period_end',{ascending:false});if(error)throw error;return (data||[]) as ProfitDistributionRow[]}
export async function createProfitDistribution(reportVersionId:string,offeringId:string,companySharePercent=60,investorPoolPercent=40,notes='Distribusi hasil dari laporan keuangan published.'){const companyBps=Math.round(companySharePercent*100),investorBps=Math.round(investorPoolPercent*100);if(companyBps<0||investorBps<0||companyBps+investorBps!==10000)throw new Error('Porsi perusahaan dan investor harus berjumlah 100%.');const {data,error}=await client().schema('app').rpc('create_profit_distribution',{p_offering_id:offeringId,p_financial_report_version_id:reportVersionId,p_company_share_bps:companyBps,p_investor_pool_bps:investorBps,p_notes:notes.trim()||null});if(error)throw error;return data}
export async function regenerateProfitAllocations(distributionId:string){const {data,error}=await client().schema('app').rpc('regenerate_profit_distribution_allocations',{p_distribution_id:distributionId});if(error)throw error;return data}
export async function transitionProfitDistribution(distributionId:string,target:'review'|'approved'|'payable'){const {data,error}=await client().schema('app').rpc('transition_profit_distribution',{p_distribution_id:distributionId,p_target:target});if(error)throw error;return data}
export type ProfitDistributionAllocationRow={id:string;distribution_id:string;investor_id:string;allocation_amount:number;status:string;payment_reference:string|null;paid_at:string|null;paid_by:string|null};
export async function getProfitDistributionReconciliation(distributionId:string){const {data,error}=await client().schema('app').rpc('profit_distribution_reconciliation',{p_distribution_id:distributionId});if(error)throw error;const x:any=data||{};return {...x,revenue_total:Number(x.revenue_total||0),expense_total:Number(x.expense_total||0),accounting_net_profit:Number(x.accounting_net_profit||0),program_opex_rate_bps:Number(x.program_opex_rate_bps||0),program_opex_amount:Number(x.program_opex_amount||0),distributable_profit:Number(x.distributable_profit||0),company_share_bps:Number(x.company_share_bps||0),investor_cap_bps:Number(x.investor_cap_bps||0),eligible_investor_bps:Number(x.eligible_investor_bps||0),investor_pool_amount:Number(x.investor_pool_amount||0),company_retained_amount:Number(x.company_retained_amount||0),allocated_amount:Number(x.allocated_amount||0),paid_amount:Number(x.paid_amount||0),outstanding_amount:Number(x.outstanding_amount||0),allocation_matches_pool:Boolean(x.allocation_matches_pool)}}
export async function getProfitDistributionPayableReadiness(distributionId:string){const {data,error}=await client().schema('app').rpc('profit_distribution_payable_readiness',{p_distribution_id:distributionId});if(error)throw error;const x:any=data||{};return {...x,investor_pool_amount:Number(x.investor_pool_amount||0),allocated_amount:Number(x.allocated_amount||0),pending_allocations:Number(x.pending_allocations||0),missing_payout_details:Number(x.missing_payout_details||0),snapshot_valid:Boolean(x.snapshot_valid),allocation_matches_pool:Boolean(x.allocation_matches_pool),ready_to_payable:Boolean(x.ready_to_payable)}}
export async function getProfitDistributionGlReconciliation(distributionId:string){const {data,error}=await client().schema('app').rpc('profit_distribution_gl_reconciliation',{p_distribution_id:distributionId});if(error)throw error;const x:any=data||{};return {...x,investor_pool_amount:Number(x.investor_pool_amount||0),payable_gl_amount:Number(x.payable_gl_amount||0),paid_allocation_amount:Number(x.paid_allocation_amount||0),cash_movement_amount:Number(x.cash_movement_amount||0),payout_gl_amount:Number(x.payout_gl_amount||0),payable_matches_pool:Boolean(x.payable_matches_pool),paid_matches_cash:Boolean(x.paid_matches_cash),cash_matches_payout_gl:Boolean(x.cash_matches_payout_gl),reconciled:Boolean(x.reconciled)}}
export async function listProfitDistributionAllocations(distributionId:string){const {data,error}=await client().from('profit_distribution_allocations').select('id,distribution_id,investor_id,allocation_amount,status,payment_reference,paid_at,paid_by').eq('distribution_id',distributionId).order('allocation_amount',{ascending:false});if(error)throw error;return (data||[]) as ProfitDistributionAllocationRow[]}
export async function uploadProfitDistributionProof(allocation:ProfitDistributionAllocationRow,file:File,paymentReference:string){if(!paymentReference.trim())throw new Error('Referensi pembayaran wajib diisi.');const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'-');const path=allocation.investor_id+'/'+allocation.id+'/'+crypto.randomUUID()+'-'+safe;const up=await client().storage.from('profit-distribution-proofs').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(up.error)throw up.error;const {data,error}=await client().schema('app').rpc('register_profit_distribution_payment_proof',{p_allocation_id:allocation.id,p_storage_path:path,p_original_file_name:file.name,p_mime_type:file.type||'application/octet-stream',p_file_size_bytes:file.size,p_payment_reference:paymentReference.trim()});if(error){await client().storage.from('profit-distribution-proofs').remove([path]);throw error}return data}
export async function markProfitDistributionAllocationPaid(allocationId:string,paymentReference?:string){const {data,error}=await client().schema('app').rpc('mark_profit_distribution_allocation_paid',{p_allocation_id:allocationId,p_payment_reference:paymentReference?.trim()||null});if(error)throw error;return data}

